__ht__function(json, dm, view, datas) {//滚动条不可见
graphView.setScrollBarVisible(false);
var rolltable15 = [], rolltable30 = [], rolltable45 = [], rolltable60 = [], coldtable = [], linetable40 = [], linetable80 = [];
