    for (let i = 1; i <= count; i++) {
        const tag = `${prefix}-${i}`;
        const node = dataModel.getDataByTag(tag);
        if (node) {
            targetArray.push(node);
        }
    }
}

// 加载各类节点
loadNodes('a', rolltable15);
loadNodes('b', rolltable30);
loadNodes('c', rolltable45);
loadNodes('d', rolltable60);
loadNodes('cold', coldtable);
loadNodes('e', linetable40);
loadNodes('f', linetable80);
var allTables = [
    ...rolltable15,
    ...rolltable30,
    ...rolltable45,
    ...rolltable60,
    ...coldtable,
    ...linetable40,
    ...linetable80
];
console.log(allTables)
// 辊道属性字段定义
const attributes = ['rollnum', 'rollPieceID', 'rollcolor'];
// 冷床属性字段定义
const attrcold = ['rolltype1', 'rollnum1', 'rolltype2', 'rollnum2', 'rollcolor'];
// 链条小车字段定义
const attrLine = ['rollnum', 'rollPieceID', "linetype", 'rollcolor'];


// rollnum 区间映射表
const rollMap = [
    { max: 15, list: rolltable15 },
    { max: 30, list: rolltable30 },
    { max: 45, list: rolltable45 },
    { max: 60, list: rolltable60 }
];

// linenum 区间映射表
