            if (mapping) {
                const targetNodes = mapping.list;
                // 根据当前的映射，设置可见性
                if (mapping.list === rolltable15) {
                    roll15.s('2d.visible', true);  // 设置 roll15 可见
                    roll30.s('2d.visible', false); // 设置 roll30 不可见
                    roll45.s('2d.visible', false); // 设置 roll45 不可见
                    roll60.s('2d.visible', false); // 设置 roll60 不可见
                    console.log('只设置 roll15 可见');
                } else if (mapping.list === rolltable30) {
                    roll15.s('2d.visible', false); // 设置 roll15 不可见
                    roll30.s('2d.visible', true);  // 设置 roll30 可见
                    roll45.s('2d.visible', false); // 设置 roll45 不可见
                    roll60.s('2d.visible', false); // 设置 roll60 不可见
                    console.log('只设置 roll30 可见');
