                    roll30.s('2d.visible', false); // 设置 roll30 不可见
                    roll45.s('2d.visible', true);  // 设置 roll45 可见
                    roll60.s('2d.visible', false); // 设置 roll60 不可见
                    console.log('只设置 roll45 可见');
