                    roll15.s('2d.visible', false); // 设置 roll15 不可见
                    roll30.s('2d.visible', false); // 设置 roll30 不可见
                    roll45.s('2d.visible', false); // 设置 roll45 不可见
                    roll60.s('2d.visible', false);  // 设置 roll60 可见
                }
                targetNodes.forEach((node, index) => {
                    const values = targetList[index];
                    // 数据行校验
                    if (Array.isArray(values) && values.length >= attributes.length) {
                        attributes.forEach((attr, i) => {
                            node.a(attr, values[i]);
                        });
                    }
                });

                console.log(`已更新到对应 roll 组：roll${mapping.max}`);
            }
        }
    }

    //冷床逻辑
    if(e.property === 'a:rolltable1'){
