        targetList.forEach(subArr => {
            // 校验：子数组是数组 + 第一个元素存在 + 第一个元素不是0（兼容字符串/数字0）
            if (
                Array.isArray(subArr) && 
                subArr[0]!== undefined && 
                subArr[0]!== '0' && 
                subArr[0]!== 0
            ) {
                countNonZeroFirst++;
            }
        });
    }
    
    // 输出计数结果（也可根据需求赋值给变量/用于后续逻辑）
    console.log('rolltable1中第一个元素不为0的数量：', countNonZeroFirst);
    count.s('text',countNonZeroFirst)
    // ********** 计数逻辑结束 **********
        // 遍历 allTables 中的所有节点
        coldtable.forEach((f, index) => {
            if (index < targetList.length) { // 确保有对应数据
                let values = targetList[index]; // 取出该节点对应的数据行
                let rolltype1 = values[0]; // rolltype1
                let rollnum1 = values[1]; // rollnum1
                let rolltype2 = values[2]; // rolltype1
