        if (Array.isArray(targetList)) {
            targetList.forEach(subArr => {
                if (Array.isArray(subArr)) {
                    const secondVal = subArr[1];
                    const isSecondValid = secondVal !== undefined && 
                                        secondVal !== null && 
                                        !Number.isNaN(secondVal) && 
                                        secondVal.toString().trim() !== '';

                    if (isSecondValid) {
                        const thirdVal = subArr[2];
                        if (thirdVal === '0' || thirdVal === 0) {
                            countThirdIs0++;
                        } else if (thirdVal === '1' || thirdVal === 1) {
                            countThirdIs1++;
                        }
                    }
                }
            });
        }

        linecount.s('text',countThirdIs0);
        carcount.s('text',countThirdIs1);
        console.log('第2位非空时，第三个元素为0的数量：', countThirdIs0);
        console.log('第2位非空时，第三个元素为1的数量：', countThirdIs1);

        // ========== 2. 核心优化：先计算最终状态，再批量更新 ==========
        // 定义默认状态（空数据时的最终状态）
        let finalLine40Visible = false;
        let finalLine80Visible = false;
        let targetNodesToUpdate = []; // 要更新数据的节点列表
        let targetListToUse = [];     // 要绑定的数据源

        // 只有数据有效时，才计算显示状态和更新列表
        if (Array.isArray(targetList) && targetList.length > 0) {
            // 查找最后一个有效行
            let lastNonEmptyRowIndex = -1;
            for (let i = targetList.length - 1; i >= 0; i--) {
                const row = targetList[i];
                if (Array.isArray(row) && row[1] !== null && row[1] !== '') {
                    lastNonEmptyRowIndex = i;
                    break;
                }
            }

            if (lastNonEmptyRowIndex !== -1) {
                const lastRow = targetList[lastNonEmptyRowIndex];
                const rollnum = lastRow[0];
                const mapping = lineMap.find(m => rollnum <= m.max);

                if (mapping) {
                    // 计算最终可见状态（直接赋值，不立即渲染）
                    if (mapping.list === linetable40) {
                        finalLine40Visible = true;
                        finalLine80Visible = false;
                    } else if (mapping.list === linetable80) {
                        finalLine40Visible = false;
                        finalLine80Visible = true;
                    }
                    // 记录要更新的节点和数据
                    targetNodesToUpdate = mapping.list;
                    targetListToUse = targetList;
                }
            }
        }

        // ========== 3. 一次性应用所有状态（关键：避免分步渲染） ==========
        // 1. 更新line可见性（只执行一次，无中间状态）
        line40.s('2d.visible', finalLine40Visible);
        line80.s('2d.visible', finalLine80Visible);

        // 2. 清空所有节点数据（只清空需要处理的节点，避免全量操作）
        const allLineNodes = [...linetable40, ...linetable80];
        allLineNodes.forEach(node => {
            attrLine.forEach(attr => {
                node.a(attr, ''); // 清空属性
            });
        });

        // 3. 只更新需要显示的节点数据（无数据时这一步跳过）
        if (targetNodesToUpdate.length > 0 && targetListToUse.length > 0) {
            targetNodesToUpdate.forEach((node, index) => {
                const values = targetListToUse[index];
                if (Array.isArray(values) && values.length >= attrLine.length) {
                    attrLine.forEach((attr, i) => {
                        node.a(attr, values[i]);
                    });
                }
            });
            console.log(`已更新到对应 line 组：${finalLine40Visible ? 'line40' : finalLine80Visible ? 'line80' : '无'}`);
        } else {
            console.log('无有效数据，清空所有链条小车');
        }
    }
});

