/**
 * 提取选中节点信息（保持原有逻辑不变）
 */
function extractSelectedNodesInfo(graphView) {
    try {
        // 验证图形视图对象结构
        if (!graphView?.sm?.()?.toSelection) {
            console.error('错误: 图形视图选择模型API不可用');
            return null;
        }
        
        const datas = graphView.sm().toSelection();
        
        // 验证选中节点数据结构
        if (!datas || !Array.isArray(datas._as)) {
            console.error('错误: 选中节点数据结构异常');
            return null;
        }
        
        // 筛选有效节点
        const filteredDatas = datas._as.filter(node => {
            const attrs = node._attrObject || {};
            const hasValidRollNum = (attrs.rollnum1?.trim() !== '') || (attrs.rollnum2?.trim() !== '');
            const tag = node._tag || node._displayName || '';
            const hasValidTag = String(tag).match(/cold-\d+/);
            return hasValidRollNum && hasValidTag;
        });
        
        // 处理无有效节点的情况
        if (filteredDatas.length === 0) {
            return { hasData: false, message: '未找到有效节点' };
        }
        
        // 从标签中提取编号
        const extractNumber = (tag) => {
            const match = String(tag || '').match(/cold-(\d+)/);
            return match ? parseInt(match[1]) : null;
        };
        
        // 按标签中的数字对有效节点进行排序
        const sortedNodes = [...filteredDatas].sort((a, b) => {
            const numA = extractNumber(a._tag);
            const numB = extractNumber(b._tag);
            return (numA || 0) - (numB || 0);
        });
        
        // 获取首尾行节点
        let firstRow = sortedNodes[0];
        let lastRow = sortedNodes[sortedNodes.length - 1];
        
        // 二次验证尾行数据有效性
        while (lastRow && (!lastRow._tag || !lastRow._attrObject || !getValidRollNum(lastRow))) {
            const lastIndex = sortedNodes.indexOf(lastRow);
            if (lastIndex <= 0) {
                console.warn('警告: 所有有效节点中只有首行数据有效，将使用首行作为尾行');
                lastRow = firstRow;
                break;
            }
            lastRow = sortedNodes[lastIndex - 1];
        }
        
            // 提前定义辅助函数（确保函数提升）
            function getValidRollNum(node) {
                if (!node._attrObject) return '';
                
                const attrs = node._attrObject;
                const rollnum1 = attrs.rollnum1?.trim() || '';
                const rollnum2 = attrs.rollnum2?.trim() || '';
                
                if (!rollnum1 && !rollnum2) {
                    console.warn(`警告: 节点 ${node._tag || '未知'} 缺少有效辊号`);
                    return '';
                }
                
                return rollnum1 || rollnum2;
            };

            // 提前定义辅助函数（确保函数提升）
            function getValidRollNum1(node) {
                if (!node._attrObject) return '';
                
                const attrs = node._attrObject;
                const rollnum1 = attrs.rollnum1?.trim() || '';
                const rollnum2 = attrs.rollnum2?.trim() || '';
                
                if (!rollnum2 && !rollnum1) {
                    console.warn(`警告: 节点 ${node._tag || '未知'} 缺少有效辊号`);
                    return '';
                }
                
                return rollnum2 || rollnum1;
            };
        
        
        // 构建结果对象
        return {
            hasData: true,
            firstRow: {
                tag: firstRow._tag || '',
                number: extractNumber(firstRow._tag),
                rollNum: getValidRollNum1(firstRow)
            },
            lastRow: {
                tag: lastRow._tag || '',
                number: extractNumber(lastRow._tag),
                rollNum: getValidRollNum(lastRow)
            },
            totalNodes: filteredDatas.length
        };
        
    } catch (error) {
        console.error('致命错误: 提取节点信息时发生异常', error);
        return null;
    }
}

/**
 * 获取接口参数（保持原有逻辑不变）
 */
function getInterfaceParameters(result) {
    if (!result || !result.hasData) {
        return {
            success: false,
            message: '无有效数据'
        };
    }
    
    return {
        success: true,
        firstNumber: result.firstRow.number,
        lastNumber: result.lastRow.number,
        firstRollNum: result.firstRow.rollNum,
        lastRollNum: result.lastRow.rollNum,
        totalNodes: result.totalNodes
    };
}


/**
 * 处理onlyNumbers（保持原有逻辑不变，新增nodeTag参数传递）
 */
function processOnlyNumbers(numbers, code, nodeTag) {
    let result = numbers;
    
    if (code >= 1 && code <= 3) {
        if (typeof nodeTag !== 'undefined') {
            result = nodeTag.replace(/\D/g, '');
        } else {
            console.error('Error: nodeTag is not defined');
        }
    } 
    else if (code === 4) {
        const extractedNumber = parseInt(nodeTag.replace(/\D/g, ''), 10);
        if (!isNaN(extractedNumber)) {
            if (extractedNumber >= 1 && extractedNumber <= 6) {
                result = (extractedNumber + 1).toString();
            } else if (extractedNumber >= 7 && extractedNumber <= 12) {
                const base = Math.floor((extractedNumber - 7) / 2) + 8;
                const suffix = (extractedNumber % 2 === 0) ? 2 : 1;
                result = `${base}${suffix}`;
            }
        }
    } 
    // 保持其他分支逻辑不变...
    else if (code === 8) {
        const mapping = {1: '1', 2: '3', 3: '2', 4: '4'};
        const extractedNumber = parseInt(nodeTag.replace(/\D/g, ''), 10);
        if (!isNaN(extractedNumber) && mapping[extractedNumber]) {
            result = mapping[extractedNumber];
        }
    } 
    else if (code === 9 || code === 10) {
        if (typeof nodeTag !== 'undefined') {
            const extractedNumber = parseInt(nodeTag.replace(/\D/g, ''), 10);
            const mapping = {1: '1', 2: '4', 3: '2', 4: '5', 5: '3', 6: '6'};
            
            if (!isNaN(extractedNumber) && mapping[extractedNumber]) {
                result = mapping[extractedNumber];
            } else {
                console.warn(`Warning: extracted number ${extractedNumber} is invalid for followcode ${code} (valid range: 1-6)`);
            }
        } else {
            console.error('Error: nodeTag is not defined');
        }
    }
    else if (code === 11) {
        if (typeof nodeTag !== 'undefined') {
            const extractedNumber = parseInt(nodeTag.replace(/\D/g, ''), 10);
            if (!isNaN(extractedNumber) && extractedNumber >= 1 && extractedNumber <= 6) {
                result = (extractedNumber - 1).toString();
            } else {
                console.warn(`Warning: extracted number ${extractedNumber} is out of range (1-6) for followcode 11`);
            }
        } else {
            console.error('Error: nodeTag is not defined');
        }
    }
    
    return result;
}

